import sys
from heapq import heappush, heappop

def maximize_average_power(n, k, m, powers):
    total_power = sum(powers)
    heap = []
    for power in powers:
        heappush(heap, (-power, power, k))

    for _ in range(m):
        if not heap:
            break
        neg_power, power, remaining = heappop(heap)
        if remaining > 0:
            power += 1
            remaining -= 1
            heappush(heap, (-power, power, remaining))
        else:
            heappush(heap, (neg_power, power, remaining))

    final_power = sum(power for _, power, _ in heap)
    return final_power / n

def main():
    n, k, m = map(int, input().split())
    powers = list(map(int, input().split()))
    result = maximize_average_power(n, k, m, powers)
    print(f"{result:.15f}")

if __name__ == "__main__":
    main()

def max_average_power(n, k, m, powers):
    def can_achieve(avg):
        total_increases = 0
        required_increases = []
        for power in powers:
            if power < avg:
                required = avg - power
                required_increases.append(required)
                total_increases += required
            else:
                required_increases.append(0)

        if total_increases > m:
            return False

        remaining_ops = m - total_increases
        increase_operations = sorted([-inc for inc in required_increases if inc > 0], reverse=True)

        for inc in increase_operations:
            if remaining_ops >= k:
                remaining_ops -= k
            else:
                remaining_ops = 0

        return remaining_ops >= 0

    left, right = min(powers), max(powers) + m
    epsilon = 1e-7

    while right - left > epsilon:
        mid = (left + right) / 2
        if can_achieve(mid):
            left = mid
        else:
            right = mid

    return left

